/* 资源已换算成编号（1..rank_n）；held/request 存编号，0 表示空 */
int check(int n, int held[][8], int held_cnt[],
          int request[][8], int req_cnt[], int out[]) {
    int bad = 0;
    for (int i = 0; i < n; i++) {
        int base = 0;                        /* 空手进程基准取 0 */
        for (int j = 0; j < held_cnt[i]; j++)
            if (held[i][j] > base) base = held[i][j];
        for (int j = 0; j < req_cnt[i]; j++)
            if (request[i][j] < base) { out[bad++] = i; break; }
    }
    return bad;                              /* 天然按下标升序 */
}

