def solve(rank, held, request):
    no = {name: i + 1 for i, name in enumerate(rank)}
    bad = []
    for i, req in enumerate(request):
        # 已持资源的最大编号，空手时取 0
        base = max((no[r] for r in held[i]), default=0)
        # 申请编号严格小于基准 ⇒ 回头申请，违规
        if any(no[r] < base for r in req):
            bad.append(i)
    return sorted(bad)

